CREATE OR REPLACE FUNCTION public.admin_set_user_role(p_user_id uuid, p_role text, p_enabled boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$ DECLARE v_role public.app_role; BEGIN IF NOT public.has_role(auth.uid(), 'admin'::public.app_role) THEN RAISE EXCEPTION 'Admin role required'; END IF; IF p_user_id IS NULL THEN RAISE EXCEPTION 'No user selected'; END IF; IF p_role NOT IN ('admin','tournament_host','tournament_moderator','match_moderator','lfg_admin','moderator','content_creator') THEN RAISE EXCEPTION 'Unknown role'; END IF; IF p_role = 'admin' AND p_user_id = auth.uid() AND NOT p_enabled THEN RAISE EXCEPTION 'You cannot remove your own admin role'; END IF; v_role := p_role::public.app_role; IF p_enabled THEN INSERT INTO public.user_roles(user_id,role) VALUES(p_user_id,v_role) ON CONFLICT(user_id,role) DO NOTHING; ELSE DELETE FROM public.user_roles WHERE user_id=p_user_id AND role=v_role; END IF; RETURN jsonb_build_object('ok',true,'roles',(SELECT coalesce(array_agg(role::text),'{}'::text[]) FROM public.user_roles WHERE user_id=p_user_id)); END; $$;